// (c) registry hookup
// ---------------------------------------------------------------------------------------------

registerDecals('crypt', [
  'decal_crypt_crack_a',
  'decal_crypt_crack_b',
  'decal_crypt_seam',
  'decal_crypt_rune',
  'decal_crypt_bonebits',
  'decal_crypt_stain',
  'decal_crypt_webcorner',
  'decal_crypt_dustpile',
]);

(DECOR_SETS['crypt'] = DECOR_SETS['crypt'] || []).push(
  'bdx_crypt_sarcophagus',
  'bdx_crypt_candlestack',
  'bdx_crypt_rubble',
  'bdx_crypt_ironfence',
  'bdx_crypt_urn'
);

(DECOR_CLUSTERS['crypt'] = DECOR_CLUSTERS['crypt'] || []).push(
  'bdx_crypt_sarcophagus',
  'bdx_crypt_ironfence'
);

// R28 W2-D HAND-EDIT — landmarks are placed explicitly by maps.js (NOT part of the
// scatter pool, or they'd carpet the map); the wisp is the biome's ambient motion.
registerLandmarks('crypt', ['lmk_crypt_mausoleum', 'lmk_crypt_obelisk']);
registerAmbient('crypt', ['bdxa_crypt_soulwisp']);

